<?php
declare(strict_types=1);namespace App\Http\Controllers;use App\Application\Projects\ProjectMatchingConfiguration;use App\Application\Projects\ProjectMatchingEngine;use App\Application\Projects\ProjectService;use App\Domain\Identity\CoreIdentity;use App\Models\PersonProfile;use App\Models\Project;use App\Models\ProjectMatchDecision;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
final class ProjectMatchingController{public function index(Request $r,Project $project,ProjectService $service,ProjectMatchingConfiguration $config,ProjectMatchingEngine $engine):View{/** @var CoreIdentity $i */$i=$r->attributes->get('dg_identity');abort_unless($service->canDecide($project,$i->reference),403);$settings=$config->get();return view('projects.matching',compact('project')+['configuration'=>$settings,'matches'=>$engine->forProject($project,$i->reference,$settings)]);}public function hide(Request $r,Project $project,string $profile,ProjectService $service):RedirectResponse{/** @var CoreIdentity $i */$i=$r->attributes->get('dg_identity');abort_unless($service->canDecide($project,$i->reference),403);PersonProfile::query()->where('discovery_reference',$profile)->firstOrFail();ProjectMatchDecision::query()->updateOrCreate(['project_id'=>$project->id,'actor_core_reference'=>$i->reference,'subject_profile_reference'=>$profile],['decision'=>ProjectMatchDecision::HIDDEN]);return back()->with('status','Suggestion masquée pour ce projet. Aucune donnée de la personne n’est modifiée.');}}
